import sys

if hasattr(sys, "set_int_max_str_digits"):
    sys.set_int_max_str_digits(0)


def parse_json(text: str) -> object:
    n = len(text)

    def skip_ws(i: int) -> int:
        while i < n:
            c = text[i]
            if c == ' ' or c == '\t' or c == '\n' or c == '\r':
                i += 1
            else:
                break
        return i

    def parse_hex4(i: int) -> tuple[int, int]:
        if i + 4 > n:
            raise ValueError
        cp = 0
        for _ in range(4):
            h = text[i]
            if '0' <= h <= '9':
                cp = (cp << 4) | (ord(h) - 48)
            elif 'a' <= h <= 'f':
                cp = (cp << 4) | (ord(h) - 97 + 10)
            elif 'A' <= h <= 'F':
                cp = (cp << 4) | (ord(h) - 65 + 10)
            else:
                raise ValueError
            i += 1
        return cp, i

    def parse_string(i: int) -> tuple[str, int]:
        if text[i] != '"':
            raise ValueError

        i += 1
        parts = []
        pos = i

        while i < n:
            c = text[i]
            if c == '"':
                if pos < i:
                    parts.append(text[pos:i])
                return ''.join(parts), i + 1

            if c == '\\':
                if pos < i:
                    parts.append(text[pos:i])

                i += 1
                if i >= n:
                    raise ValueError

                e = text[i]
                i += 1

                if e == '"':
                    parts.append('"')
                elif e == '\\':
                    parts.append('\\')
                elif e == '/':
                    parts.append('/')
                elif e == 'b':
                    parts.append('\b')
                elif e == 'f':
                    parts.append('\f')
                elif e == 'n':
                    parts.append('\n')
                elif e == 'r':
                    parts.append('\r')
                elif e == 't':
                    parts.append('\t')
                elif e == 'u':
                    cp, i = parse_hex4(i)

                    if 0xD800 <= cp <= 0xDBFF:
                        if i + 6 > n or text[i] != '\\' or text[i + 1] != 'u':
                            raise ValueError

                        low_cp, i = parse_hex4(i + 2)
                        if not (0xDC00 <= low_cp <= 0xDFFF):
                            raise ValueError

                        code_point = (
                            0x10000
                            + ((cp - 0xD800) << 10)
                            + (low_cp - 0xDC00)
                        )
                        parts.append(chr(code_point))
                    elif 0xDC00 <= cp <= 0xDFFF:
                        raise ValueError
                    else:
                        parts.append(chr(cp))
                else:
                    raise ValueError

                pos = i
            else:
                o = ord(c)
                if o < 0x20 or (0xD800 <= o <= 0xDFFF):
                    raise ValueError
                i += 1

        raise ValueError

    def parse_number(i: int) -> tuple[object, int]:
        start = i
        c = text[i]

        if c == '-':
            i += 1
            if i >= n:
                raise ValueError
            c = text[i]

        if not ('0' <= c <= '9'):
            raise ValueError

        if c == '0':
            i += 1
        else:
            i += 1
            while i < n and '0' <= text[i] <= '9':
                i += 1

        is_float = False

        if i < n and text[i] == '.':
            i += 1
            if i >= n or not ('0' <= text[i] <= '9'):
                raise ValueError
            while i < n and '0' <= text[i] <= '9':
                i += 1
            is_float = True

        if i < n and (text[i] == 'e' or text[i] == 'E'):
            i += 1
            if i < n and (text[i] == '+' or text[i] == '-'):
                i += 1
            if i >= n or not ('0' <= text[i] <= '9'):
                raise ValueError
            while i < n and '0' <= text[i] <= '9':
                i += 1
            is_float = True

        if is_float:
            return float(text[start:i]), i

        return int(text[start:i]), i

    def parse_true(i: int) -> tuple[bool, int]:
        if text.startswith('true', i):
            return True, i + 4
        raise ValueError

    def parse_false(i: int) -> tuple[bool, int]:
        if text.startswith('false', i):
            return False, i + 5
        raise ValueError

    def parse_null(i: int) -> tuple[None, int]:
        if text.startswith('null', i):
            return None, i + 4
        raise ValueError

    stack = []
    result = None

    def finish(value: object, i: int) -> tuple[bool, object, int]:
        while True:
            if not stack:
                return True, value, i

            frame = stack[-1]

            if frame[0] == 0:
                frame[1].append(value)
                i = skip_ws(i)

                if i < n and text[i] == ',':
                    i += 1
                    return False, None, i

                if i < n and text[i] == ']':
                    stack.pop()
                    value = frame[1]
                    i += 1
                    continue

                raise ValueError

            if frame[4] != 1 or frame[3] is None:
                raise ValueError

            key = frame[3]
            if key in frame[2]:
                raise ValueError

            frame[1][key] = value
            frame[2].add(key)
            frame[3] = None

            i = skip_ws(i)

            if i < n and text[i] == ',':
                i += 1
                frame[4] = 0
                return False, None, i

            if i < n and text[i] == '}':
                stack.pop()
                value = frame[1]
                i += 1
                continue

            raise ValueError

    i = skip_ws(0)
    if i >= n:
        raise ValueError

    while True:
        if stack and stack[-1][0] == 1 and stack[-1][4] == 0:
            i = skip_ws(i)
            if i >= n or text[i] != '"':
                raise ValueError

            key, i = parse_string(i)
            i = skip_ws(i)

            if i >= n or text[i] != ':':
                raise ValueError

            i += 1
            stack[-1][3] = key
            stack[-1][4] = 1
            continue

        i = skip_ws(i)
        if i >= n:
            raise ValueError

        c = text[i]

        if c == '[':
            j = skip_ws(i + 1)
            if j < n and text[j] == ']':
                i = j + 1
                done, result, i = finish([], i)
                if done:
                    break
            else:
                stack.append([0, []])
                i = j

        elif c == '{':
            j = skip_ws(i + 1)
            if j < n and text[j] == '}':
                i = j + 1
                done, result, i = finish({}, i)
                if done:
                    break
            else:
                stack.append([1, {}, set(), None, 0])
                i = j

        elif c == '"':
            value, i = parse_string(i)
            done, result, i = finish(value, i)
            if done:
                break

        elif c == 't':
            value, i = parse_true(i)
            done, result, i = finish(value, i)
            if done:
                break

        elif c == 'f':
            value, i = parse_false(i)
            done, result, i = finish(value, i)
            if done:
                break

        elif c == 'n':
            value, i = parse_null(i)
            done, result, i = finish(value, i)
            if done:
                break

        elif c == '-' or ('0' <= c <= '9'):
            value, i = parse_number(i)
            done, result, i = finish(value, i)
            if done:
                break

        else:
            raise ValueError

    i = skip_ws(i)
    if i != n:
        raise ValueError

    return result
